"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3110],{72380:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a Dodge the Teapots round.","params":[{"name":"props","desc":"","lua_type":"MinigameTypes.GameModeProps"}],"returns":[{"desc":"","lua_type":"DodgeTheTeapots"}],"function_type":"static","source":{"line":92,"path":"src/Server/Features/Minigames/GameModes/DodgeTheTeapots.luau"}},{"name":"Play","desc":"The round. Called by [BaseGameMode:Start] and yields until the countdown ends.\\n\\nWires the `Finish` part: the first time a player touches it they are declared a\\nwinner, given a placement-based reward multiplier, congratulated with confetti,\\nand returned to the spawn. Difficulty rises by 0.2 per finish. A local `winners`\\nset gates re-scoring \u2014 it is cleared 1.8s after the teleport, so a player can\\nrun the course again, but only their first finish set their multiplier.\\n\\nIn parallel a [BaseGameMode:Loop] spawns teapots in bursts of ten, waiting\\n`i / 6 / difficulty * 10` between each \u2014 so throws within a burst get *further*\\napart while rising difficulty pulls the whole burst tighter. The loop returns\\nfalse as soon as the round stops.\\n\\nFinally yields on [BaseGameMode:GameCountdown] for the configured round time.","params":[],"returns":[],"function_type":"method","source":{"line":180,"path":"src/Server/Features/Minigames/GameModes/DodgeTheTeapots.luau"}}],"properties":[],"types":[{"name":"DodgeTheTeapots","desc":"Adds no state of its own; it is a [BaseGameMode]. Per-round bookkeeping (the\\ndifficulty ramp and the set of players currently ineligible to re-score) lives\\nas locals inside `Play`.","lua_type":"BaseGameMode","source":{"line":82,"path":"src/Server/Features/Minigames/GameModes/DodgeTheTeapots.luau"}}],"name":"DodgeTheTeapots","desc":"Obstacle-course minigame. Players cross a floating platform while a stream of\\nphysics-driven teapots is fired at them; reaching the finish scores, and the\\ncourse gets harder each time someone does.\\n\\n### Rules\\n\\n- 1 player minimum, 2 lives, 120-second cap, played on `teapot_island`.\\n- Teapots are launched from the map\'s `TeapotSpawn` part with randomized\\n  position, spin, impulse and colour. Each is tagged `KILL_PART` \u2014 so the\\n  killing is handled by the shared kill-part system, not by this mode \u2014 and\\n  binned after 8 seconds.\\n- Reaching the map\'s `Finish` part records a win. Placement pays out: the first\\n  three finishers get 3.6x, 2.4x and 1.2x reward multipliers, everyone after\\n  gets 1x.\\n- Every finish raises `difficulty` by 0.2, tightening the spawn interval \u2014 the\\n  course escalates against the field as a whole rather than on a fixed curve.\\n- Finishers are teleported back to the start after a beat and, 1.8s later,\\n  allowed to score again. Re-runs raise the difficulty again but the player is\\n  already a winner, so the extra laps only make the round harder for everyone.\\n\\n### BaseGameMode hooks\\n\\nImplements [BaseGameMode] `Play` only \u2014 no `Init`. `Play` wires the finish-line\\ntouch handler, starts a [BaseGameMode:Loop] that spawns teapots in bursts of\\nten at an ever-shortening interval, and then yields on\\n[BaseGameMode:GameCountdown] for the round\'s duration.\\n\\nThe mode does not set `disableWinnerCheck`, so [BaseGameMode:PlayerCheck] ends\\nthe round early once every remaining player has finished at least once.\\n\\nGated by [FeatureFlags].Minigames \u2014 disabled by default; per-project forks\\nenable it deliberately.","tags":["dormant"],"realm":["Server"],"source":{"line":42,"path":"src/Server/Features/Minigames/GameModes/DodgeTheTeapots.luau"}}')}}]);